const userPassword = `-- name: UserPassword :one
SELECT u.username, c.secret
FROM user u LEFT JOIN credential c ON c.user_id = u.id AND c.kind = 'password'
WHERE u.id = ?1
`

type UserPasswordRow struct {
	Username string
	Secret   sql.NullString
}

// A user's username and password hash, by ID.
func (q *Queries) UserPassword(ctx context.Context, argID id.ID) (UserPasswordRow, error) {
	row := q.db.QueryRowContext(ctx, userPassword, argID)
	var i UserPasswordRow
	err := row.Scan(&i.Username, &i.Secret)
	return i, err
}

const userSessions = `-- name: UserSessions :many
SELECT id, user_id, kind, name, platform, created_at, last_used_at, app, app_version, os_version, device_model
FROM session WHERE user_id = ?1
`

type UserSessionsRow struct {
	ID          id.ID
	UserID      id.ID
	Kind        string
	Name        string
	Platform    string
	CreatedAt   int64
	LastUsedAt  int64
	App         string
	AppVersion  string
	OsVersion   string
	DeviceModel string
}

func (q *Queries) UserSessions(ctx context.Context, userID id.ID) ([]UserSessionsRow, error) {
	rows, err := q.db.QueryContext(ctx, userSessions, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UserSessionsRow
	for rows.Next() {
		var i UserSessionsRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Kind,
			&i.Name,
			&i.Platform,
			&i.CreatedAt,
			&i.LastUsedAt,
			&i.App,
			&i.AppVersion,
			&i.OsVersion,
			&i.DeviceModel,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
